; cpir.asm -- chapter 13: a byte searched for with CPIR
; generated by gen13.py
        INCLUDE "msx.inc"
        OUTPUT "cpir.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; Chapter 11's list of 32 bytes searched with CPIR for the first, the
; eleventh, the last, and a byte that is not there. The debugger reads HL,
; BC and the flags after each search, and the time.
init:   di
        ld sp, SYS_AREA
        scf                     ; the carry set: CPIR leaves it alone
        ld a, $11
        ld hl, list
s0:     ld bc, 32
        cpir
e0:     nop
        ld a, $A7
        ld hl, list
s1:     ld bc, 32
        cpir
e1:     nop
        ld a, $E2
        ld hl, list
s2:     ld bc, 32
        cpir
e2:     nop
        ld a, $07
        ld hl, list
s3:     ld bc, 32
        cpir
e3:     nop
stop:   jr stop

list:   db $11, $20, $2F, $3E, $4D, $5C, $6B, $7A, $89, $98, $A7, $B6, $C5, $D4, $E3, $F2, $01, $10, $1F, $2E, $3D, $4C, $5B, $6A, $79, $88, $97, $A6, $B5, $C4, $D3, $E2
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
